package com.medtrack.inventory.service;
import com.medtrack.inventory.entity.*; import com.medtrack.inventory.repository.InventoryJournalEntryRepository; import com.medtrack.user.entity.User; import jakarta.persistence.EntityManager; import java.time.Year; import java.util.*; import org.springframework.stereotype.Service;
@Service public class DoubleEntryLedgerService { private final InventoryJournalEntryRepository journals; private final EntityManager entityManager; public DoubleEntryLedgerService(InventoryJournalEntryRepository j,EntityManager em){journals=j;entityManager=em;} public InventoryJournalEntry record(JournalEntryType type,String referenceType,UUID referenceId,User actor,String description,List<InventoryLedgerLine> lines){if(lines==null||lines.size()<2)throw new IllegalArgumentException("A journal requires at least two ledger lines");int debit=lines.stream().filter(l->l.getDirection()==LedgerDirection.DEBIT).mapToInt(InventoryLedgerLine::getQuantity).sum();int credit=lines.stream().filter(l->l.getDirection()==LedgerDirection.CREDIT).mapToInt(InventoryLedgerLine::getQuantity).sum();if(debit!=credit)throw new IllegalArgumentException("Unbalanced inventory journal");InventoryJournalEntry entry=new InventoryJournalEntry(nextNumber(),type,referenceType,referenceId,actor,description);lines.forEach(entry::addLine);return journals.save(entry);} private String nextNumber(){Number value=(Number)entityManager.createNativeQuery("select nextval('medtrack_journal_number_seq')").getSingleResult();return "JRN-"+Year.now().getValue()+"-%06d".formatted(value.longValue());} }
